// Packaged, bilingual content. Source references form the maintenance/coverage inventory;
// they are never rendered as implementation details in the user interface.
export type HelpText = { en: string; pt: string };
export const text = (en: string, pt: string): HelpText => ({ en, pt });
export type HelpDestination = 'graph' | 'drafts' | 'general' | 'workspaces' | 'account' | 'anara';
export const helpCategories = [
  ['start', 'Getting started', 'Primeiros passos'],
  ['workspaces', 'Workspaces & collaboration', 'Workspaces e colaboração'],
  ['papers', 'Papers & PDFs', 'Artigos e PDFs'],
  ['graph', 'Research graph', 'Mapa de investigação'],
  ['groups', 'Groups & notes', 'Grupos e notas'],
  ['latex', 'LaTeX editor', 'Editor LaTeX'],
  ['research', 'Discovery & AI', 'Descoberta e IA'],
  ['settings', 'Settings & account', 'Definições e conta'],
  ['trouble', 'Troubleshooting', 'Resolver problemas'],
  ['shortcuts', 'Keyboard & gestures', 'Teclado e gestos'],
] as const;
export type HelpCategory = typeof helpCategories[number][0];
export type HelpGuide = {
  id: string; category: HelpCategory; title: HelpText; summary: HelpText;
  keywords: string[]; steps: HelpText[]; tips: HelpText[]; requirements: HelpText[];
  related: string[]; sources: string[]; destination?: HelpDestination;
};
type Pair = [string, string];
function guide(id: string, category: HelpCategory, title: Pair, summary: Pair, keywords: string[],
  steps: Pair[], tips: Pair[], related: string[], sources: string[], destination?: HelpDestination, requirements: Pair[] = []): HelpGuide {
  return { id, category, title: text(...title), summary: text(...summary), keywords,
    steps: steps.map(p => text(...p)), tips: tips.map(p => text(...p)), requirements: requirements.map(p => text(...p)), related, sources, destination };
}
